// Neuron Class


class Neuron {

    // Type declaration

    bias = 0

    weights: number[]

    inputs: number[]

    target: number


    constructor(inputs: number[], weights: number[], bias: number, target: number) {
        this.bias = bias
        this.weights = weights
        this.inputs = inputs
        this.target = target
    }

    /** Neuron activation or the Machine Learning term, forward propagation */

    forward() {

        let output = 0

        // Multiplying inputs by weights

        for (let i = 0; i < this.inputs.length; i++) {

            output += this.inputs[i] * this.weights[i]

        }

        output += this.bias

        return output

    }

    /**  The L1 loss (Mean Absolute Error) loss Function
     * :
     * Doesnt find Mean or Sum because it outputs a scalar, or 1 dimensional value
    */

    loss(output: number) {

        return Math.abs(this.target - output)

    }

    /** Backpropagation Function, or learning function*/

    backward(output: number, learning_rate: number = 0.001) {

        // Loss gradient/derivative
        let lossGradient = 0

        if (output > this.target) {
            lossGradient = 1
        } else if (output < this.target) {
            lossGradient = -1
        }

        // Calculating gradients 
        for (let i = 0; i < this.weights.length; i++) {

            let gradientWeight = lossGradient * this.inputs[i]

            this.weights[i] -= learning_rate * gradientWeight

        }

        let gradientBias = lossGradient

        this.bias -= learning_rate * gradientBias

    }


}

